def atomic_patch(initial, ops):
    def _is_int(value):
        return type(value) is int

    def _is_string(value):
        return isinstance(value, str)

    original_state = dict(initial)
    state = dict(initial)

    allowed_ops = {"set", "add", "delete", "assert"}

    for index, op in enumerate(ops):
        op_name = op.get("op")
        if op_name not in allowed_ops:
            return {
                "committed": False,
                "state": dict(initial),
                "failed_at": index,
            }

        key = op.get("key")
        if not _is_string(key):
            return {
                "committed": False,
                "state": dict(initial),
                "failed_at": index,
            }

        if op_name == "set":
            value = op.get("value")
            if not _is_int(value):
                return {
                    "committed": False,
                    "state": dict(initial),
                    "failed_at": index,
                }
            state[key] = value

        elif op_name == "add":
            value = op.get("value")
            if not _is_int(value):
                return {
                    "committed": False,
                    "state": dict(initial),
                    "failed_at": index,
                }
            state[key] = state.get(key, 0) + value

        elif op_name == "delete":
            if key in state:
                del state[key]

        elif op_name == "assert":
            value = op.get("value")
            if not _is_int(value):
                return {
                    "committed": False,
                    "state": dict(initial),
                    "failed_at": index,
                }
            if key not in state or state[key] != value:
                return {
                    "committed": False,
                    "state": dict(initial),
                    "failed_at": index,
                }

    return {
        "committed": True,
        "state": state,
        "failed_at": None,
    }
