from collections import defaultdict, deque


def schedule_tasks(tasks, workers):
    if not isinstance(workers, int) or isinstance(workers, bool) or workers <= 0:
        raise ValueError("workers must be a positive integer")

    if not tasks:
        return {}

    # Validate task structure and build normalized dependency sets.
    normalized = {}
    for name, info in tasks.items():
        if not isinstance(info, dict):
            raise ValueError("task info must be a dict")

        duration = info.get("duration")
        if not isinstance(duration, int) or isinstance(duration, bool) or duration < 0:
            raise ValueError("duration must be a non-negative integer")

        deps = info.get("deps", [])
        if deps is None:
            deps = []

        dep_set = set()
        for dep in deps:
            if dep not in tasks:
                raise ValueError("missing dependency")
            dep_set.add(dep)

        normalized[name] = {
            "duration": duration,
            "deps": dep_set,
        }

    # Detect dependency cycles.
    indegree = {name: len(normalized[name]["deps"]) for name in normalized}
    dependents = defaultdict(list)

    for name, info in normalized.items():
        for dep in info["deps"]:
            dependents[dep].append(name)

    q = deque(name for name, deg in indegree.items() if deg == 0)
    seen = 0

    while q:
        name = q.popleft()
        seen += 1
        for nxt in dependents[name]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                q.append(nxt)

    if seen != len(normalized):
        raise ValueError("dependency cycle detected")

    completed = set()
    result = {}

    # worker_id -> end_time, or None if idle
    busy_until = [None] * workers

    # end_time -> set of task names finishing at that time
    finish_events = defaultdict(set)

    current_time = 0

    def process_completions(time):
        if time not in finish_events:
            return
        finished = finish_events.pop(time)
        completed.update(finished)

    def executable_tasks():
        return sorted(
            name
            for name in normalized
            if name not in completed
            and all(dep in completed for dep in normalized[name]["deps"])
        )

    def next_idle_worker():
        for worker_id, end_time in enumerate(busy_until):
            if end_time is None or end_time <= current_time:
                return worker_id
        return None

    def nearest_completion_time():
        candidates = []
        for end_time in busy_until:
            if end_time is not None and end_time > current_time:
                candidates.append(end_time)
        if finish_events:
            candidates.append(min(finish_events.keys()))
        return min(candidates) if candidates else None

    while len(completed) < len(normalized):
        # First, process all tasks completing at the current time.
        process_completions(current_time)

        # Assign as many tasks as possible at this time.
        while True:
            ready = executable_tasks()
            if not ready:
                break

            worker_id = next_idle_worker()
            if worker_id is None:
                break

            task_name = ready[0]
            duration = normalized[task_name]["duration"]

            start_time = current_time
            end_time = start_time + duration

            result[task_name] = [start_time, end_time, worker_id]

            if duration == 0:
                # Zero-duration tasks complete immediately.
                completed.add(task_name)
                # Continue assigning at the same time.
                continue

            # Occupy this worker until end_time.
            busy_until[worker_id] = end_time
            finish_events[end_time].add(task_name)

        # If all tasks are done, stop.
        if len(completed) == len(normalized):
            break

        # No more tasks can be assigned now; jump to the nearest completion time.
        next_time = nearest_completion_time()
        if next_time is None:
            # Should not happen if validation is correct, but guard against it.
            raise ValueError("no schedulable tasks remain")

        current_time = next_time

    return result
