def capped_allocate(total, weights, caps):
    n = len(weights)
    result = [0] * n

    if total == 0:
        return result

    unfrozen = list(range(n))
    remaining = total

    while unfrozen:
        weight_sum = sum(weights[i] for i in unfrozen)

        if weight_sum == 0:
            break

        to_freeze = []
        for i in unfrozen:
            if remaining * weights[i] >= caps[i] * weight_sum:
                to_freeze.append(i)

        if to_freeze:
            for i in to_freeze:
                result[i] = caps[i]
                remaining -= caps[i]

            frozen_set = set(to_freeze)
            unfrozen = [i for i in unfrozen if i not in frozen_set]
            continue

        quotas = []
        quota_sum = 0
        for i in unfrozen:
            q = (remaining * weights[i]) // weight_sum
            quotas.append((i, q))
            quota_sum += q

        extra = remaining - quota_sum

        if extra > 0:
            order = sorted(
                unfrozen,
                key=lambda i: (-(remaining * weights[i] % weight_sum), i)
            )
            for i in order[:extra]:
                result[i] += 1

        for i, q in quotas:
            result[i] += q

        break

    return result
