import re


def select_rows(rows, query):
    """
    Return 0-based indices of rows satisfying a boolean query.

    Query grammar:
      expr      := or_expr
      or_expr   := and_expr ('|' and_expr)*
      and_expr  := not_expr ('&' not_expr)*
      not_expr  := '!' not_expr | primary
      primary   := '(' expr ')' | atom
      atom      := identifier '==' json_literal

    json_literal:
      double-quoted JSON string, integer, true, false, null

    Raises ValueError for empty query, illegal characters, incomplete
    expressions, or trailing tokens.
    """
    if not isinstance(query, str):
        raise ValueError("query must be a string")

    parser = _QueryParser(query)
    ast = parser.parse_expression()
    parser.expect_end()

    result = []
    for index, row in enumerate(rows):
        if _evaluate(ast, row):
            result.append(index)
    return result


class _QueryParser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.length = len(text)

    def _skip_whitespace(self):
        while self.pos < self.length and self.text[self.pos].isspace():
            self.pos += 1

    def _peek(self):
        if self.pos < self.length:
            return self.text[self.pos]
        return None

    def _expect(self, ch):
        self._skip_whitespace()
        if self.pos >= self.length or self.text[self.pos] != ch:
            raise ValueError("expected '{}'".format(ch))
        self.pos += 1

    def _expect_string(self, s):
        self._skip_whitespace()
        if self.text[self.pos:self.pos + len(s)] != s:
            raise ValueError("expected '{}'".format(s))
        self.pos += len(s)

    def parse_expression(self):
        self._skip_whitespace()
        if self.pos >= self.length:
            raise ValueError("empty query")
        return self._parse_or()

    def expect_end(self):
        self._skip_whitespace()
        if self.pos < self.length:
            raise ValueError("trailing token")

    def _parse_or(self):
        left = self._parse_and()
        while True:
            self._skip_whitespace()
            if self._peek() == '|':
                self.pos += 1
                right = self._parse_and()
                left = ('or', left, right)
            else:
                break
        return left

    def _parse_and(self):
        left = self._parse_not()
        while True:
            self._skip_whitespace()
            if self._peek() == '&':
                self.pos += 1
                right = self._parse_not()
                left = ('and', left, right)
            else:
                break
        return left

    def _parse_not(self):
        self._skip_whitespace()
        if self._peek() == '!':
            self.pos += 1
            child = self._parse_not()
            return ('not', child)
        return self._parse_primary()

    def _parse_primary(self):
        self._skip_whitespace()
        ch = self._peek()
        if ch is None:
            raise ValueError("incomplete expression")
        if ch == '(':
            self.pos += 1
            expr = self._parse_or()
            self._expect(')')
            return expr
        return self._parse_atom()

    def _parse_atom(self):
        self._skip_whitespace()
        field = self._parse_identifier()
        self._expect('==')
        value = self._parse_json_literal()
        return ('atom', field, value)

    def _parse_identifier(self):
        self._skip_whitespace()
        start = self.pos
        if start >= self.length:
            raise ValueError("incomplete expression")

        ch = self.text[start]
        if not ('A' <= ch <= 'Z' or 'a' <= ch <= 'z' or ch == '_'):
            raise ValueError("invalid identifier")

        self.pos += 1
        while self.pos < self.length:
            ch = self.text[self.pos]
            if ('A' <= ch <= 'Z' or 'a' <= ch <= 'z' or
                '0' <= ch <= '9' or ch == '_'):
                self.pos += 1
            else:
                break

        return self.text[start:self.pos]

    def _parse_json_literal(self):
        self._skip_whitespace()
        ch = self._peek()
        if ch is None:
            raise ValueError("incomplete expression")

        if ch == 't':
            self._expect_string('true')
            return True
        if ch == 'f':
            self._expect_string('false')
            return False
        if ch == 'n':
            self._expect_string('null')
            return None
        if ch == '"':
            return self._parse_json_string()
        if ch == '-' or '0' <= ch <= '9':
            return self._parse_json_integer()

        raise ValueError("invalid JSON literal")

    def _parse_json_integer(self):
        start = self.pos
        if self._peek() == '-':
            self.pos += 1

        if self.pos >= self.length or not self.text[self.pos].isdigit():
            raise ValueError("invalid JSON integer")

        if self.text[self.pos] == '0':
            self.pos += 1
            if self.pos < self.length and self.text[self.pos].isdigit():
                raise ValueError("invalid JSON integer")
        else:
            while self.pos < self.length and self.text[self.pos].isdigit():
                self.pos += 1

        return int(self.text[start:self.pos])

    def _parse_json_string(self):
        self.pos += 1  # consume opening quote
        chars = []

        while self.pos < self.length:
            ch = self.text[self.pos]

            if ch == '"':
                self.pos += 1
                return ''.join(chars)

            if ch == '\\':
                self.pos += 1
                if self.pos >= self.length:
                    raise ValueError("invalid JSON string escape")

                esc = self.text[self.pos]
                self.pos += 1

                if esc == '"':
                    chars.append('"')
                elif esc == '\\':
                    chars.append('\\')
                elif esc == '/':
                    chars.append('/')
                elif esc == 'b':
                    chars.append('\b')
                elif esc == 'f':
                    chars.append('\f')
                elif esc == 'n':
                    chars.append('\n')
                elif esc == 'r':
                    chars.append('\r')
                elif esc == 't':
                    chars.append('\t')
                elif esc == 'u':
                    chars.append(self._parse_unicode_escape())
                else:
                    raise ValueError("invalid JSON string escape")
                continue

            if ord(ch) < 0x20:
                raise ValueError("invalid JSON string control character")

            chars.append(ch)
            self.pos += 1

        raise ValueError("unterminated JSON string")

    def _parse_unicode_escape(self):
        if self.pos + 4 > self.length:
            raise ValueError("invalid JSON unicode escape")

        hex_digits = self.text[self.pos:self.pos + 4]
        if not re.fullmatch(r'[0-9a-fA-F]{4}', hex_digits):
            raise ValueError("invalid JSON unicode escape")

        self.pos += 4
        code = int(hex_digits, 16)

        # Support JSON surrogate pairs.
        if 0xD800 <= code <= 0xDBFF:
            if self.pos + 6 > self.length:
                raise ValueError("invalid JSON unicode surrogate pair")
            if self.text[self.pos:self.pos + 2] != '\\u':
                raise ValueError("invalid JSON unicode surrogate pair")

            self.pos += 2
            low_hex = self.text[self.pos:self.pos + 4]
            if not re.fullmatch(r'[0-9a-fA-F]{4}', low_hex):
                raise ValueError("invalid JSON unicode surrogate pair")

            self.pos += 4
            low = int(low_hex, 16)
            if not (0xDC00 <= low <= 0xDFFF):
                raise ValueError("invalid JSON unicode surrogate pair")

            code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)

        return chr(code)


def _evaluate(node, row):
    kind = node[0]

    if kind == 'atom':
        _, field, literal = node
        try:
            value = row[field]
        except (KeyError, TypeError, IndexError):
            return False
        return _json_equal(value, literal)

    if kind == 'not':
        return not _evaluate(node[1], row)

    if kind == 'and':
        return _evaluate(node[1], row) and _evaluate(node[2], row)

    if kind == 'or':
        return _evaluate(node[1], row) or _evaluate(node[2], row)

    raise ValueError("invalid query node")


def _json_equal(value, literal):
    # JSON booleans are distinct from JSON integers.
    if isinstance(literal, bool):
        return isinstance(value, bool) and value == literal

    if literal is None:
        return value is None

    if isinstance(literal, int):
        return isinstance(value, int) and not isinstance(value, bool) and value == literal

    if isinstance(literal, str):
        return isinstance(value, str) and value == literal

    return False
