import json
import re


def select_rows(rows, query):
    """
    Return 0-based indices of rows satisfying a boolean query.

    Query grammar:
      expr       := or_expr
      or_expr    := and_expr ('|' and_expr)*
      and_expr   := not_expr ('&' not_expr)*
      not_expr   := '!' not_expr | primary
      primary    := '(' expr ')' | comparison
      comparison := identifier '==' json_literal

    JSON literals supported:
      double-quoted strings, integers, true, false, null

    Missing fields always compare False.
    Comparison is JSON type/value aware: true != 1.
    """
    if not isinstance(query, str):
        raise ValueError("query must be a string")

    query = query.strip()
    if not query:
        raise ValueError("empty query")

    tokens = _tokenize(query)
    parser = _Parser(tokens)
    predicate = parser.parse_expression()
    parser.expect_end()

    result = []
    for i, row in enumerate(rows):
        if predicate(row):
            result.append(i)
    return result


class _Token:
    __slots__ = ("kind", "value", "pos")

    def __init__(self, kind, value, pos):
        self.kind = kind
        self.value = value
        self.pos = pos


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("incomplete expression")
        self.pos += 1
        return tok

    def expect(self, kind):
        tok = self.peek()
        if tok is None or tok.kind != kind:
            raise ValueError("incomplete expression")
        return self.consume()

    def expect_end(self):
        if self.pos != len(self.tokens):
            raise ValueError("trailing token")

    def parse_expression(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.peek() and self.peek().kind == "|":
            self.consume()
            right = self.parse_and()
            left = _or_pred(left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.peek() and self.peek().kind == "&":
            self.consume()
            right = self.parse_not()
            left = _and_pred(left, right)
        return left

    def parse_not(self):
        tok = self.peek()
        if tok and tok.kind == "!":
            self.consume()
            operand = self.parse_not()
            return _not_pred(operand)
        return self.parse_primary()

    def parse_primary(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("incomplete expression")

        if tok.kind == "(":
            self.consume()
            expr = self.parse_expression()
            self.expect(")")
            return expr

        if tok.kind == "ident":
            self.consume()
            self.expect("==")
            literal_tok = self.peek()
            if literal_tok is None or literal_tok.kind != "literal":
                raise ValueError("incomplete expression")
            self.consume()
            return _comparison_pred(tok.value, literal_tok.value)

        raise ValueError("incomplete expression")


def _tokenize(query):
    tokens = []
    i = 0
    n = len(query)

    while i < n:
        ch = query[i]

        if ch.isspace():
            i += 1
            continue

        if ch == "!":
            tokens.append(_Token("!", True, i))
            i += 1
            continue

        if ch == "&":
            tokens.append(_Token("&", True, i))
            i += 1
            continue

        if ch == "|":
            tokens.append(_Token("|", True, i))
            i += 1
            continue

        if ch == "(":
            tokens.append(_Token("(", True, i))
            i += 1
            continue

        if ch == ")":
            tokens.append(_Token(")", True, i))
            i += 1
            continue

        if ch == "=":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append(_Token("==", True, i))
                i += 2
                continue
            raise ValueError("illegal character")

        if ch == '"':
            start = i
            i += 1
            while i < n:
                c = query[i]
                if c == "\\":
                    if i + 1 >= n:
                        raise ValueError("illegal character")
                    i += 2
                elif c == '"':
                    i += 1
                    break
                else:
                    i += 1
            else:
                raise ValueError("illegal character")

            raw = query[start:i]
            try:
                value = json.loads(raw)
            except Exception:
                raise ValueError("illegal character")
            if not isinstance(value, str):
                raise ValueError("illegal character")
            tokens.append(_Token("literal", value, start))
            continue

        if ch == "-" or ch.isdigit():
            start = i
            if ch == "-":
                i += 1
                if i >= n or not query[i].isdigit():
                    raise ValueError("illegal character")
            while i < n and query[i].isdigit():
                i += 1
            raw = query[start:i]
            try:
                value = json.loads(raw)
            except Exception:
                raise ValueError("illegal character")
            if not isinstance(value, int) or isinstance(value, bool):
                raise ValueError("illegal character")
            tokens.append(_Token("literal", value, start))
            continue

        if ch == "t" and query.startswith("true", i):
            tokens.append(_Token("literal", True, i))
            i += 4
            continue

        if ch == "f" and query.startswith("false", i):
            tokens.append(_Token("literal", False, i))
            i += 5
            continue

        if ch == "n" and query.startswith("null", i):
            tokens.append(_Token("literal", None, i))
            i += 4
            continue

        if re.match(r"[A-Za-z_]", ch):
            start = i
            i += 1
            while i < n and re.match(r"[A-Za-z0-9_]", query[i]):
                i += 1
            tokens.append(_Token("ident", query[start:i], start))
            continue

        raise ValueError("illegal character")

    return tokens


def _get_field(row, name):
    try:
        return row[name]
    except Exception:
        return _MISSING


_MISSING = object()


def _json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return a is b
    if isinstance(a, int) and isinstance(b, int):
        return a == b
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    if a is None and b is None:
        return True
    return False


def _comparison_pred(name, literal):
    def pred(row):
        value = _get_field(row, name)
        if value is _MISSING:
            return False
        return _json_equal(value, literal)
    return pred


def _not_pred(p):
    def pred(row):
        return not p(row)
    return pred


def _and_pred(p, q):
    def pred(row):
        return p(row) and q(row)
    return pred


def _or_pred(p, q):
    def pred(row):
        return p(row) or q(row)
    return pred
