def atomic_patch(initial, ops):
    """
    原子执行一组字典补丁操作。

    参数:
        initial: dict[str, int]，初始状态。
        ops: list[dict]，按顺序执行的操作。

    返回:
        成功:
            {'committed': True, 'state': 最终状态, 'failed_at': None}
        失败:
            {'committed': False, 'state': 原始状态副本, 'failed_at': 首个失败操作下标}
    """

    def _is_strict_int(value):
        return isinstance(value, int) and not isinstance(value, bool)

    original_state = dict(initial)
    state = dict(initial)

    allowed_ops = {"set", "add", "delete", "assert"}

    for index, op in enumerate(ops):
        if not isinstance(op, dict):
            return {
                "committed": False,
                "state": dict(original_state),
                "failed_at": index,
            }

        op_name = op.get("op")
        if op_name not in allowed_ops:
            return {
                "committed": False,
                "state": dict(original_state),
                "failed_at": index,
            }

        key = op.get("key")
        if not isinstance(key, str):
            return {
                "committed": False,
                "state": dict(original_state),
                "failed_at": index,
            }

        if op_name == "delete":
            state.pop(key, None)
            continue

        if "value" not in op:
            return {
                "committed": False,
                "state": dict(original_state),
                "failed_at": index,
            }

        value = op["value"]
        if not _is_strict_int(value):
            return {
                "committed": False,
                "state": dict(original_state),
                "failed_at": index,
            }

        if op_name == "set":
            state[key] = value

        elif op_name == "add":
            current = state.get(key, 0)
            state[key] = current + value

        elif op_name == "assert":
            if key not in state or state[key] != value:
                return {
                    "committed": False,
                    "state": dict(original_state),
                    "failed_at": index,
                }

    return {
        "committed": True,
        "state": state,
