            value = op.get("value")
            if not is_strict_int(value):
                return fail(index)
            state[key] = value

        elif op_name == "add":
            value = op.get("value")
            if not is_strict_int(value):
                return fail(index)
            state[key] = state.get(key, 0) + value

        elif op_name == "delete":
            state.pop(key, None)

        elif op_name == "assert":
            value = op.get("value")
            if not is_strict_int(value):
                return fail(index)
            if key not in state or state[key] != value:
                return fail(index)

    return {
        "committed": True,
        "state": state,
        "failed_at": None,
