import heapq


def schedule_tasks(tasks, workers):
    if not isinstance(workers, int) or isinstance(workers, bool) or workers <= 0:
        raise ValueError("workers must be a positive integer")

    if not isinstance(tasks, dict):
        raise ValueError("tasks must be a dictionary")

    # Copy input to avoid modifying it.
    task_info = {}
    for name, info in tasks.items():
        if not isinstance(info, dict):
            raise ValueError("each task must be a dictionary")
        if "duration" not in info or "deps" not in info:
            raise ValueError("each task must contain 'duration' and 'deps'")

        duration = info["duration"]
        if not isinstance(duration, int) or isinstance(duration, bool) or duration < 0:
            raise ValueError("duration must be a non-negative integer")

        deps = info["deps"]
        if not isinstance(deps, (list, tuple, set)):
            raise ValueError("deps must be a list, tuple, or set")

        # Treat dependencies as a set.
        dep_set = set(deps)
        task_info[name] = {
            "duration": duration,
            "deps": dep_set,
        }

    # Validate missing dependencies.
    for name, info in task_info.items():
        for dep in info["deps"]:
            if dep not in task_info:
                raise ValueError(f"missing dependency: {dep}")

    # Detect cycles using Kahn's algorithm.
    indegree = {name: 0 for name in task_info}
    dependents = {name: [] for name in task_info}

    for name, info in task_info.items():
        for dep in info["deps"]:
            indegree[name] += 1
            dependents[dep].append(name)

    queue = [name for name, deg in indegree.items() if deg == 0]
    heapq.heapify(queue)

    processed = 0
    while queue:
        node = heapq.heappop(queue)
        processed += 1
        for nxt in dependents[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(queue, nxt)

    if processed != len(task_info):
        raise ValueError("dependency cycle detected")

    # Empty task set.
    if not task_info:
        return {}

    completed = set()
    running = {}  # worker_id -> (task_name, end_time)
    completion_heap = []  # (end_time, worker_id, task_name)
    idle_workers = list(range(workers))
    heapq.heapify(idle_workers)

    results = {}
    current_time = 0

    def is_executable(task_name):
        if task_name in completed or task_name in {t for _, t in running.values()}:
            return False
        return all(dep in completed for dep in task_info[task_name]["deps"])

    while len(completed) < len(task_info):
        # Process all tasks completed at current_time.
        while completion_heap and completion_heap[0][0] == current_time:
            end_time, worker_id, task_name = heapq.heappop(completion_heap)
            if task_name in completed:
                continue
            completed.add(task_name)
            results[task_name] = [results[task_name][0], end_time, worker_id]
            running.pop(worker_id, None)
            heapq.heappush(idle_workers, worker_id)

        # Assign tasks at current_time.
        while True:
            if not idle_workers:
                break

            executable = sorted(
                name for name in task_info
                if is_executable(name)
            )

            if not executable:
                break

            task_name = executable[0]
            worker_id = heapq.heappop(idle_workers)
            duration = task_info[task_name]["duration"]

            results[task_name] = [current_time, current_time + duration, worker_id]

            if duration == 0:
                completed.add(task_name)
                results[task_name] = [current_time, current_time, worker_id]
                heapq.heappush(idle_workers, worker_id)
                continue

            end_time = current_time + duration
            running[worker_id] = (task_name, end_time)
            heapq.heappush(completion_heap, (end_time, worker_id, task_name))

        if len(completed) == len(task_info):
            break

        if not completion_heap:
            # Should not happen after cycle validation, but guard anyway.
            raise ValueError("unable to schedule remaining tasks")

        # Jump to the nearest completion time.
        current_time = completion_heap[0][0]

    return results
