import re
from typing import Any, List, Tuple, Union


_MISSING = object()
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _parse_json_string(s: str, i: int) -> Tuple[str, int]:
    if i >= len(s) or s[i] != '"':
        raise ValueError("invalid string literal")

    i += 1
    out = []

    while i < len(s):
        ch = s[i]

        if ch == '"':
            return "".join(out), i + 1

        if ch == "\\":
            i += 1
            if i >= len(s):
                raise ValueError("unterminated string escape")

            esc = s[i]
            i += 1

            if esc == '"':
                out.append('"')
            elif esc == "\\":
                out.append("\\")
            elif esc == "/":
                out.append("/")
            elif esc == "b":
                out.append("\b")
            elif esc == "f":
                out.append("\f")
            elif esc == "n":
                out.append("\n")
            elif esc == "r":
                out.append("\r")
            elif esc == "t":
                out.append("\t")
            elif esc == "u":
                if i + 4 > len(s):
                    raise ValueError("invalid unicode escape")

                hex_part = s[i:i + 4]
                if not re.fullmatch(r"[0-9a-fA-F]{4}", hex_part):
                    raise ValueError("invalid unicode escape")

                code = int(hex_part, 16)
                i += 4

                if 0xD800 <= code <= 0xDBFF:
                    if i + 6 <= len(s) and s[i] == "\\" and s[i + 1] == "u":
                        low_hex = s[i + 2:i + 6]
                        if re.fullmatch(r"[0-9a-fA-F]{4}", low_hex):
                            low = int(low_hex, 16)
                            if 0xDC00 <= low <= 0xDFFF:
                                code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)
                                i += 6

                if 0xD800 <= code <= 0xDFFF:
                    raise ValueError("invalid unicode escape")

                out.append(chr(code))
            else:
                raise ValueError("invalid string escape")

        else:
            if ord(ch) < 0x20:
                raise ValueError("invalid control character in string")
            out.append(ch)
            i += 1

    raise ValueError("unterminated string literal")


def _parse_json_integer(s: str, i: int) -> Tuple[int, int]:
    start = i

    if i < len(s) and s[i] == "-":
        i += 1

    if i >= len(s) or not s[i].isdigit():
        raise ValueError("invalid integer literal")

    if s[i] == "0":
        i += 1
        if i < len(s) and s[i].isdigit():
            raise ValueError("invalid integer literal")
    else:
        while i < len(s) and s[i].isdigit():
            i += 1

    return int(s[start:i]), i


def _tokenize(query: str) -> List[Tuple[str, Any]]:
    tokens = []
    i = 0
    n = len(query)

    while i < n:
        ch = query[i]

        if ch.isspace():
            i += 1
            continue

        if ch == "(":
            tokens.append(("(", None))
            i += 1
            continue

        if ch == ")":
            tokens.append((")", None))
            i += 1
            continue

        if ch == "!":
            tokens.append(("!", None))
            i += 1
            continue

        if ch == "&":
            tokens.append(("&", None))
            i += 1
            continue

        if ch == "|":
            tokens.append(("|", None))
            i += 1
            continue

        if ch == "=":
            if i + 1 >= n or query[i + 1] != "=":
                raise ValueError("invalid token")
            tokens.append(("==", None))
            i += 2
            continue

        if ch == '"':
            value, i = _parse_json_string(query, i)
            tokens.append(("STRING", value))
            continue

        if ch == "-" or ch.isdigit():
            value, i = _parse_json_integer(query, i)
            tokens.append(("INT", value))
            continue

        if ch.isalpha() or ch == "_":
            match = _IDENT_RE.match(query, i)
            if not match:
                raise ValueError("invalid identifier")

            word = match.group(0)
            i = match.end()

            if word == "true":
                tokens.append(("BOOL", True))
            elif word == "false":
                tokens.append(("BOOL", False))
            elif word == "null":
                tokens.append(("NULL", None))
            else:
                tokens.append(("IDENT", word))

            continue

        raise ValueError("illegal character")

    return tokens


def _parse_query(query: str) -> Any:
    if not isinstance(query, str):
        raise ValueError("query must be a string")

    tokens = _tokenize(query)
    if not tokens:
        raise ValueError("empty query")

    pos = 0

    def peek() -> Tuple[str, Any]:
        return tokens[pos] if pos < len(tokens) else (None, None)

    def consume(expected: str = None) -> Tuple[str, Any]:
        nonlocal pos

        if pos >= len(tokens):
            raise ValueError("incomplete expression")

        token = tokens[pos]

        if expected is not None and token[0] != expected:
            raise ValueError("unexpected token")

        pos += 1
        return token

    def parse_or():
        node = parse_and()

        while peek()[0] == "|":
            consume("|")
            right = parse_and()
            node = ("or", node, right)

        return node

    def parse_and():
        node = parse_not()

        while peek()[0] == "&":
            consume("&")
            right = parse_not()
            node = ("and", node, right)

        return node

    def parse_not():
        if peek()[0] == "!":
            consume("!")
            return ("not", parse_not())

        return parse_primary()

    def parse_primary():
        token_type, _ = peek()

        if token_type == "(":
            consume("(")
            node = parse_or()
            consume(")")
            return node

        if token_type == "IDENT":
            field = consume("IDENT")[1]
            consume("==")

            literal_type, literal_value = consume()

            if literal_type not in ("STRING", "INT", "BOOL", "NULL"):
                raise ValueError("invalid literal")

            return ("cmp", field, literal_type, literal_value)

        raise ValueError("incomplete expression")

    ast = parse_or()

    if pos != len(tokens):
        raise ValueError("trailing tokens")

    return ast


def _json_type(value: Any) -> str:
    if value is None:
        return "null"

    if isinstance(value, bool):
        return "bool"

    if isinstance(value, str):
        return "string"

    if isinstance(value, int):
        return "number"

    if isinstance(value, float):
        return "number"

    return "other"


def _json_equal(left: Any, right: Any) -> bool:
    left_type = _json_type(left)
    right_type = _json_type(right)

    if left_type != right_type:
        return False

    if left_type == "null":
        return True

    if left_type == "bool":
        return left is right

    if left_type == "string":
        return left == right

    if left_type == "number":
        return left == right

    return False


def _get_field(row: Any, field: str) -> Any:
    try:
        return row[field]
    except (KeyError, IndexError, TypeError, AttributeError):
        return _MISSING


def _evaluate(node: Any, row: Any) -> bool:
    kind = node[0]

    if kind == "or":
        return _evaluate(node[1], row) or _evaluate(node[2], row)

    if kind == "and":
        return _evaluate(node[1], row) and _evaluate(node[2], row)

    if kind == "not":
        return not _evaluate(node[1], row)

    if kind == "cmp":
        _, field, literal_type, literal_value = node
        value = _get_field(row, field)

        if value is _MISSING:
            return False

        if literal_type == "NULL":
            return value is None

        if literal_type == "BOOL":
            return isinstance(value, bool) and value is literal_value

        if literal_type == "STRING":
            return isinstance(value, str) and value == literal_value

        if literal_type == "INT":
            if isinstance(value, bool):
                return False

            if isinstance(value, int):
                return value == literal_value

            if isinstance(value, float):
                return value == literal_value

            return False

        return False

    raise ValueError("invalid AST node")


def select_rows(rows, query):
    ast = _parse_query(query)
    return [index for index, row in enumerate(rows) if _evaluate(ast, row)]
