import copy


def reconcile_events(events):
    """
    对事件列表进行调和。

    规则：
    - 全局相同 id 只处理第一次，后续同 id 事件忽略。
    - 每个 key 由 (version, source) 字典序最大的有效事件决定。
    - 若 (version, source) 相同，则较晚到达的有效事件胜出。
    - delete 是墓碑，阻止较旧 put 复活。
    - 返回 values 中只包含当前可见键值。
    - 返回 versions 中包含所有见过的 key 及其最终胜出事件的 [version, source]。
    - 返回值中的嵌套 JSON 与输入不共享可变对象。
    - 不修改输入。
    """
    seen_ids = set()

    # key -> {
    #   "version": int,
    #   "source": str,
    #   "arrival": int,
    #   "op": "put" | "delete",
    #   "value": any,
    # }
    best_by_key = {}

    for arrival, event in enumerate(events):
        event_id = event["id"]

        if event_id in seen_ids:
            continue
        seen_ids.add(event_id)

        key = event["key"]
        version = event["version"]
        source = event["source"]
        op = event["op"]

        if op == "put":
            value = copy.deepcopy(event["value"])
        elif op == "delete":
            value = None
        else:
            # 按题意只会出现 put/delete；若出现其他 op，忽略。
            continue

        current = best_by_key.get(key)

        if current is None:
            best_by_key[key] = {
                "version": version,
                "source": source,
                "arrival": arrival,
                "op": op,
                "value": value,
            }
            continue

        current_tuple = (current["version"], current["source"])
        event_tuple = (version, source)

        should_replace = False

        if event_tuple > current_tuple:
            should_replace = True
        elif event_tuple == current_tuple:
            # 同版本同来源：默认较晚到达者胜出。
            # 但 delete 是墓碑：如果当前胜出事件是 delete，
            # 不允许同版本同来源的 put 复活它。
            if current["op"] == "delete" and op == "put":
                should_replace = False
            elif arrival > current["arrival"]:
                should_replace = True

        if should_replace:
            best_by_key[key] = {
                "version": version,
                "source": source,
                "arrival": arrival,
                "op": op,
                "value": value,
            }

    values = {}
    versions = {}

    for key, best in best_by_key.items():
        versions[key] = [best["version"], best["source"]]

        if best["op"] == "put":
            values[key] = copy.deepcopy(best["value"])

    return {
        "values": values,
        "versions": versions,
    }
