import re
from collections.abc import Mapping


class _Token:
    __slots__ = ("kind", "value", "pos")

    def __init__(self, kind, value, pos):
        self.kind = kind
        self.value = value
        self.pos = pos

    def __repr__(self):
        return f"Token({self.kind!r}, {self.value!r}, {self.pos})"


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        if self.i < len(self.tokens):
            return self.tokens[self.i]
        return None

    def next(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("unexpected end of query")
        self.i += 1
        return tok

    def expect(self, kind):
        tok = self.next()
        if tok.kind != kind:
            raise ValueError(f"expected {kind}, got {tok.kind}")
        return tok

    def parse(self):
        if not self.tokens:
            raise ValueError("empty query")
        node = self.parse_or()
        if self.i != len(self.tokens):
            raise ValueError("trailing tokens")
        return node

    def parse_or(self):
        left = self.parse_and()
        while True:
            tok = self.peek()
            if tok is not None and tok.kind == "OR":
                self.next()
                right = self.parse_and()
                left = ("or", left, right)
            else:
                return left

    def parse_and(self):
        left = self.parse_unary()
        while True:
            tok = self.peek()
            if tok is not None and tok.kind == "AND":
                self.next()
                right = self.parse_unary()
                left = ("and", left, right)
            else:
                return left

    def parse_unary(self):
        tok = self.peek()
        if tok is not None and tok.kind == "NOT":
            self.next()
            operand = self.parse_unary()
            return ("not", operand)
        return self.parse_primary()

    def parse_primary(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("unexpected end of query")

        if tok.kind == "LPAREN":
            self.next()
            node = self.parse_or()
            self.expect("RPAREN")
            return node

        if tok.kind == "IDENT":
            self.next()
            self.expect("EQ")
            literal = self.parse_literal()
            return ("cmp", tok.value, literal)

        raise ValueError(f"unexpected token {tok.kind}")

    def parse_literal(self):
        tok = self.next()

        if tok.kind == "STRING":
            return tok.value

        if tok.kind == "INT":
            return tok.value

        if tok.kind == "IDENT":
            if tok.value == "true":
                return True
            if tok.value == "false":
                return False
            if tok.value == "null":
                return None

        raise ValueError("invalid literal")


def _tokenize(query):
    if not isinstance(query, str):
        raise ValueError("query must be a string")

    tokens = []
    i = 0
    n = len(query)

    ident_re = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
    int_re = re.compile(r"-?(?:0|[1-9][0-9]*)")

    while i < n:
        ch = query[i]

        if ch.isspace():
            i += 1
            continue

        if ch == "!":
            tokens.append(_Token("NOT", "!", i))
            i += 1
            continue

        if ch == "&":
            tokens.append(_Token("AND", "&", i))
            i += 1
            continue

        if ch == "|":
            tokens.append(_Token("OR", "|", i))
            i += 1
            continue

        if ch == "(":
            tokens.append(_Token("LPAREN", "(", i))
            i += 1
            continue

        if ch == ")":
            tokens.append(_Token("RPAREN", ")", i))
            i += 1
            continue

        if ch == "=":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append(_Token("EQ", "==", i))
                i += 2
                continue
            raise ValueError("invalid character '='")

        if ch == '"':
            value, i = _parse_json_string(query, i)
            tokens.append(_Token("STRING", value, i))
            continue

        m = ident_re.match(query, i)
        if m:
            tokens.append(_Token("IDENT", m.group(0), i))
            i = m.end()
            continue

        m = int_re.match(query, i)
        if m:
            text = m.group(0)
            # Reject JSON numbers with leading zeros like 01, but allow 0 and -0.
            if len(text) > 1 and text[0] != "-" and text[0] == "0":
                raise ValueError("invalid integer literal")
            if len(text) > 2 and text[0] == "-" and text[1] == "0" and len(text) > 2:
                raise ValueError("invalid integer literal")
            tokens.append(_Token("INT", int(text), i))
            i = m.end()
            continue

        raise ValueError(f"invalid character {ch!r}")

    return tokens


def _parse_json_string(s, start):
    # s[start] == '"'
    i = start + 1
    n = len(s)
    out = []

    while i < n:
        ch = s[i]

        if ch == '"':
            return "".join(out), i + 1

        if ch == "\\":
            i += 1
            if i >= n:
                raise ValueError("unterminated string escape")

            esc = s[i]
            i += 1

            if esc == '"':
                out.append('"')
            elif esc == "\\":
                out.append("\\")
            elif esc == "/":
                out.append("/")
            elif esc == "b":
                out.append("\b")
            elif esc == "f":
                out.append("\f")
            elif esc == "n":
                out.append("\n")
            elif esc == "r":
                out.append("\r")
            elif esc == "t":
                out.append("\t")
            elif esc == "u":
                if i + 4 > n:
                    raise ValueError("invalid unicode escape")
                hex_digits = s[i:i + 4]
                if not re.fullmatch(r"[0-9a-fA-F]{4}", hex_digits):
                    raise ValueError("invalid unicode escape")
                code = int(hex_digits, 16)
                i += 4

                # Handle surrogate pairs as JSON does.
                if 0xD800 <= code <= 0xDBFF:
                    if i + 6 <= n and s[i] == "\\" and s[i + 1] == "u":
                        low_hex = s[i + 2:i + 6]
                        if re.fullmatch(r"[0-9a-fA-F]{4}", low_hex):
                            low = int(low_hex, 16)
                            if 0xDC00 <= low <= 0xDFFF:
                                code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)
                                i += 6
                out.append(chr(code))
            else:
                raise ValueError("invalid string escape")

            continue

        if ord(ch) < 0x20:
            raise ValueError("invalid control character in string")

        out.append(ch)
        i += 1

    raise ValueError("unterminated string")


def _json_equal(value, literal):
    if literal is None:
        return value is None

    if isinstance(literal, bool):
        return isinstance(value, bool) and value == literal

    if isinstance(literal, int):
        if isinstance(value, bool):
            return False
        if isinstance(value, int):
            return value == literal
        if isinstance(value, float):
            return value == literal and value.is_integer()
        return False

    if isinstance(literal, str):
        return isinstance(value, str) and value == literal

    return False


def _get_field(row, field):
    if isinstance(row, Mapping):
        if field in row:
            return True, row[field]
        return False, None

    # Fallback for simple object-like rows.
    try:
        return True, getattr(row, field)
    except AttributeError:
        return False, None


def _evaluate(node, row):
    kind = node[0]

    if kind == "or":
        return _evaluate(node[1], row) or _evaluate(node[2], row)

    if kind == "and":
        return _evaluate(node[1], row) and _evaluate(node[2], row)

    if kind == "not":
        return not _evaluate(node[1], row)

    if kind == "cmp":
        _, field, literal = node
        found, value = _get_field(row, field)
        if not found:
            return False
        return _json_equal(value, literal)

    raise ValueError("invalid AST node")


def select_rows(rows, query):
    tokens = _tokenize(query)
    ast = _Parser(tokens).parse()

    result = []
    for idx, row in enumerate(rows):
        if _evaluate(ast, row):
            result.append(idx)

    return result
