def schedule_tasks(tasks, workers):
    if not isinstance(workers, int) or isinstance(workers, bool) or workers <= 0:
        raise ValueError("workers must be a positive integer")

    if not isinstance(tasks, dict):
        raise ValueError("tasks must be a dictionary")

    if not tasks:
        return {}

    task_names = list(tasks.keys())
    task_set = set(task_names)

    duration = {}
    deps = {}

    for name in task_names:
        info = tasks[name]
        if not isinstance(info, dict):
            raise ValueError("each task must be a dictionary")

        if "duration" not in info or "deps" not in info:
            raise ValueError("each task must contain 'duration' and 'deps'")

        d = info["duration"]
        if isinstance(d, bool) or not isinstance(d, int) or d < 0:
            raise ValueError("duration must be a non-negative integer")

        dep_list = info["deps"]
        if not isinstance(dep_list, (list, tuple, set)):
            raise ValueError("deps must be an iterable of task names")

        dep_set = set()
        for dep in dep_list:
            if dep not in task_set:
                raise ValueError("missing dependency")
            dep_set.add(dep)

        duration[name] = d
        deps[name] = dep_set

    # Cycle detection via Kahn's algorithm.
    indegree = {name: len(deps[name]) for name in task_names}
    dependents = {name: [] for name in task_names}

    for name in task_names:
        for dep in deps[name]:
            dependents[dep].append(name)

    queue = sorted([name for name in task_names if indegree[name] == 0])
    processed = 0

    while queue:
        name = queue.pop(0)
        processed += 1

        for nxt in dependents[name]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                queue.append(nxt)

        queue.sort()

    if processed != len(task_names):
        raise ValueError("dependency cycle detected")

    pending = set(task_names)
    completed = set()
    running = {}  # worker_id -> (task_name, end_time)
    idle_workers = set(range(workers))
    result = {}

    current_time = 0

    while pending or running:
        # Process all tasks completed at current_time.
        finished_workers = []
        for worker_id, (task_name, end_time) in running.items():
            if end_time == current_time:
                finished_workers.append(worker_id)

        for worker_id in finished_workers:
            task_name, _ = running.pop(worker_id)
            completed.add(task_name)
            idle_workers.add(worker_id)

        # Assign as many tasks as possible at current_time.
        while True:
            if not pending or not idle_workers:
                break

            executable = []
            for task_name in pending:
                if deps[task_name].issubset(completed):
                    executable.append(task_name)

            if not executable:
                break

            executable.sort()
            task_name = executable[0]
            worker_id = min(idle_workers)

            pending.remove(task_name)
            start_time = current_time
            end_time = current_time + duration[task_name]

            if duration[task_name] == 0:
                completed.add(task_name)
                result[task_name] = [start_time, end_time, worker_id]
                # Worker remains idle; continue assigning immediately.
            else:
                running[worker_id] = (task_name, end_time)
                idle_workers.remove(worker_id)
                result[task_name] = [start_time, end_time, worker_id]

        if not pending and not running:
            break

        if running:
            current_time = min(end_time for _, end_time in running.values())
        else:
            # No running tasks and no assignable pending task.
            # With valid acyclic dependencies this should not happen.
            raise ValueError("dependency cycle detected")

    return result
