def atomic_patch(initial, ops):
    def is_int(value):
        return type(value) is int

    def is_str(value):
        return isinstance(value, str)

    original_state = dict(initial)
    state = dict(initial)

    for index, op in enumerate(ops):
        op_name = op.get('op')
        if op_name not in ('set', 'add', 'delete', 'assert'):
            return {
                'committed': False,
                'state': dict(original_state),
                'failed_at': index
            }

        if 'key' not in op or not is_str(op['key']):
            return {
                'committed': False,
                'state': dict(original_state),
                'failed_at': index
            }

        key = op['key']

        if op_name == 'set':
            if 'value' not in op or not is_int(op['value']):
                return {
                    'committed': False,
                    'state': dict(original_state),
                    'failed_at': index
                }
            state[key] = op['value']

        elif op_name == 'add':
            if 'value' not in op or not is_int(op['value']):
                return {
                    'committed': False,
                    'state': dict(original_state),
                    'failed_at': index
                }
            state[key] = state.get(key, 0) + op['value']

        elif op_name == 'delete':
            state.pop(key, None)

        elif op_name == 'assert':
            if 'value' not in op or not is_int(op['value']):
                return {
                    'committed': False,
                    'state': dict(original_state),
                    'failed_at': index
                }
            if key not in state or state[key] != op['value']:
                return {
                    'committed': False,
                    'state': dict(original_state),
                    'failed_at': index
                }

    return {
        'committed': True,
        'state': state,
        'failed_at': None
    }
