import heapq

def interval_overlay(updates, lo, hi):
    if lo == hi:
        return []

    events = {}

    def add_event(coord, kind, uid):
        if coord not in events:
            events[coord] = ([], [])
        events[coord][kind].append(uid)

    for uid, upd in enumerate(updates):
        s = upd["start"]
        e = upd["end"]

        if s >= e:
            continue

        s = max(s, lo)
        e = min(e, hi)

        if s >= e:
            continue

        add_event(s, 0, uid)
        add_event(e, 1, uid)

    coords = sorted(events.keys())

    if not coords:
        return [[lo, hi, None]]

    if coords[0] != lo:
        coords.insert(0, lo)
    if coords[-1] != hi:
        coords.append(hi)

    active = set()
    heap = []
    result = []

    prev = None

    def current_value():
        while heap:
            _, _, uid = heap[0]
            if uid in active:
                return updates[uid]["value"]
            heapq.heappop(heap)
        return None

    def append_segment(start, end, value):
        if start >= end:
            return
        if result and result[-1][2] == value and result[-1][1] == start:
            result[-1][1] = end
        else:
            result.append([start, end, value])

    for coord in coords:
        if prev is not None and prev < coord:
            append_segment(prev, coord, current_value())

        if coord in events:
            starts, ends = events[coord]

            for uid in ends:
                active.discard(uid)

            for uid in starts:
                active.add(uid)
                priority = updates[uid]["priority"]
                heapq.heappush(heap, (-priority, -uid, uid))

        prev = coord

    return result
